def weighted_distance_sums(n: int, edges: list[list[int]], w: list[int]) -> list[int]:
    g = [[] for _ in range(n)]
    for a, b in edges:
        g[a].append(b)
        g[b].append(a)

    parent = [-1] * n
    order = []
    seen = [False] * n
    stack = [0]
    seen[0] = True
    while stack:
        u = stack.pop()
        order.append(u)
        for v in g[u]:
            if not seen[v]:
                seen[v] = True
                parent[v] = u
                stack.append(v)

    sub_w = list(w)
    for u in reversed(order):
        p = parent[u]
        if p >= 0:
            sub_w[p] += sub_w[u]

    sub_s = [0] * n
    for u in reversed(order):
        s = 0
        pu = parent[u]
        for v in g[u]:
            if v != pu:
                s += sub_s[v] + sub_w[v]
        sub_s[u] = s

    total = sub_w[0]
    ans = [0] * n
    ans[0] = sub_s[0]
    for u in order:
        pu = parent[u]
        base = ans[u]
        for v in g[u]:
            if v != pu:
                ans[v] = base + total - 2 * sub_w[v]
    return ans
